import{_ as t}from"./chunks/765f70cdb1e5c2bf01fc.D9VQzCi6.js";import{_ as r,C as l,o,c as i,j as e,a as n,E as s,a6 as h}from"./chunks/framework.CnPv4DE1.js";const q=JSON.parse('{"title":"如何快速实现大目标，快到感觉像是作弊","description":"","frontmatter":{"title":"如何快速实现大目标，快到感觉像是作弊","originalTitle":"How To Achieve Big Goals So Fast It Feels Like Cheating","date":"2025-03-08","originalUrl":"https://thedankoe.com/letters/why-you-fail-at-almost-everything-you-do/","minutes":14,"sourceHash":"fff945e2c9aa1ffe85f1f35dddac2145aead9e2ff7fb6e60b504fdf79cee37f4","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/why-you-fail-at-almost-everything-you-do/"}]]},"headers":[],"relativePath":"letters/why-you-fail-at-almost-everything-you-do.md","filePath":"letters/why-you-fail-at-almost-everything-you-do.md"}'),m={name:"letters/why-you-fail-at-almost-everything-you-do.md"};function c(d,p,u,f,b,_){const a=l("ArticleMeta");return o(),i("div",null,[p[0]||(p[0]=e("h1",{id:"如何快速实现大目标-快到感觉像是作弊",tabindex:"-1"},[n("如何快速实现大目标，快到感觉像是作弊 "),e("a",{class:"header-anchor",href:"#如何快速实现大目标-快到感觉像是作弊","aria-label":'Permalink to "如何快速实现大目标，快到感觉像是作弊"'},"​")],-1)),s(a),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/0cSwXV2FAJ8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>如果你想理解为什么大多数人都无法成就任何伟大的事情，你需要理解这一点：</p><blockquote><p>习得性无助是一种心理状态，指一个人或动物在某种特定情境中学会了表现出无助感，即便逃避或摆脱这种情境的机会确实存在。这种状态是在个体反复经历无法控制的负面刺激（例如痛苦、失败）之后产生的。结果就是，他们开始相信自己的行动对环境没有任何影响，于是放弃了改变现状的努力。</p></blockquote><p>你认识这样的人。</p><p>你大概有那种朋友，永远不相信自己做不到任何事——不，我说反了。你大概有那种朋友，永远相信自己做不到任何事。跟他们聊天很难受，因为这真的很让人沮丧。就像，老兄，你怎么就看不出来这是有可能的？</p><p>你在网上到处都能看到这种现象。</p><p>人们甚至都不再去<em>尝试</em>了，而这背后有一个深层的原因。</p><p>当他们面对创业、认识新朋友，或从整体上改变生活的机会时，他们那无意识的、自动化的、被编程好的反应是：</p><ul><li>听起来像是骗局</li><li>我做不到那件事，因为……</li><li>但如果它不成功怎么办？</li></ul><p>这是他们自我发展中的一个致命缺陷。</p><p>这被称为<em>选择性怀疑主义</em>。</p><p>他们的心智无法看到一个自己表现良好的潜在未来。他们的信念把自己的思绪困在一个狭小的泡泡里，动弹不得。他们的注意力无法超越问题本身。而如果你的决定塑造了你的未来，你就能明白，这种状态只会导向一种平庸的人生。</p><p>残酷的真相是这样的：</p><p>你还没有失败够。</p><p>你放弃得太早了，你没有学会把失败视为通往成功的唯一路径。</p><p>现在，成功主要取决于你能否赢得低我与高我之间的内在博弈。这是一场心智游戏，而当你接受负面结果是你人生唯一可能的结果时，你就输掉了这场游戏。</p><p>当你培养出一种能够在生活的任何领域中蓬勃发展的心智时，你就赢得了这场游戏。</p><p>所以这就是我们需要做的事，我在这篇文章里为你准备了几个技巧：</p><ol><li>如何像历史上最成功的人一样成为战略思考者。我们会拆解7条原则。</li><li>如何在开始之前就用“事前验尸法”（Pre-Mortem Technique）模拟失败（这样你就能提前让自己的心智准备好去做困难的事）。</li></ol><p>但首先，我们需要从零开始。</p><p>你需要先有<em>信念</em>，然后才能有效地<em>行动</em>。</p><p>你需要学会如何重新编程自己的心智，让它去热爱失败与不确定性。</p><h2 id="赢得这场心智游戏" tabindex="-1">赢得这场心智游戏 <a class="header-anchor" href="#赢得这场心智游戏" aria-label="Permalink to &quot;赢得这场心智游戏&quot;">​</a></h2><blockquote><p>你在哲学中的目标是什么？——为了给苍蝇指出一条飞出瓶子的路。</p><p>路德维希·维特根斯坦</p></blockquote><p>你有一个想要打造的项目。</p><p>你有一个想要实现的目标。</p><p>你对自己想要过的生活有一个构想。</p><p>它可能是赚到几百万美元，和一个你无法想象没有他/她的人结婚，减肥，学一项技能，或者其他任何能带来成长的事情——因为人类天生就有一种冲动，要不断打破一个又一个外壳，然后再打破下一个，再下一个。</p><p>事情是这样的：</p><p>一切都是一场心智游戏，而这场心智游戏又嵌套在一场更大的心智游戏之中。</p><p>要玩好这场心智游戏，你必须理解心智是如何运作的。</p><p>在谈论具体的实践步骤之前，我们要先深入一点。</p><p>如果你跳过了对失败根本原因的理解，那些实践步骤对你没有丝毫帮助。</p><p>跟着我，试着去理解。</p><p>让我们来剖析一下心智，这样你就能改变自己的心智：</p><h3 id="_1-——-心智作为一种解释性滤镜" tabindex="-1">1 —— 心智作为一种解释性滤镜 <a class="header-anchor" href="#_1-——-心智作为一种解释性滤镜" aria-label="Permalink to &quot;1 —— 心智作为一种解释性滤镜&quot;">​</a></h3><p>心智是通过故事来理解世界的。</p><p>故事是由符号编织而成的网络，构成一幅更宏大的图景。</p><p>游戏则是一种互动式的故事，由需要实现的具有挑战性的目标、需要遵守的规则，以及你可以选择去采取、并能带来技能提升的行动所组成。</p><p>故事，或者说游戏，为心智提供了一个“框架”，用来维持秩序与清晰。它给了你通往终极目标的、能带来满足感的一步步行动。</p><p>而如果你不理解自己正在经历的那个故事，或者自己正在玩的那场游戏，你就无法弄清楚自己在这个世界上的位置。你会失去目的感。混乱随之而来，你迷失在无序之中。</p><p>事情是这样的，每个人都在经历一个故事，但大多数人并不清楚这个故事是什么，或者它将把自己引向何处。</p><p>换句话说，他们还没有像我们即将要做的那样，制定出一套策略。</p><p>他们追逐的是父母和社会灌进他们脑子里的那些无意识的目标。他们在玩的是“做一个有用的打工人”这场游戏，而不是成为一个自由且充实的个体。</p><p>人们试图带着一个雇员或胖子被编程好的心智，去玩创业或减肥这场游戏，然后诧异自己为何失败。他们不明白，要在人生中实现任何事，你必须<em>成为</em>那个既能看到这种可能性、又具备实现它所需技能的人。</p><p>你的心智如何解读这个世界，很大程度上取决于你的<em>身份认同——你是谁</em>。</p><p>你的身份认同是由一系列想法、信念、目标和价值观构成的网络，它起着一种心理“滤镜”的作用。</p><ul><li>你会注意到那些能帮你实现目标（或者赢得这场游戏）的信息。</li><li>你会注意到那些与你所看重的东西、也就是你的价值观（游戏的规则）相符的信息。</li><li>你会注意到那些能证实你信念（你认为这场游戏应该怎么玩）的信息。</li></ul><p>两个不同的人，有着不同的目标，玩着不同的游戏，读同一本书，却能得出完全不同的结论。</p><p>而那些结论随后被用来做决定。那些决定不断叠加复合，最终导向成功或失败。</p><p>你明白这为什么重要吗？</p><p><em>你在几乎所有事情上都失败，是因为你没能以一种能为你提供真正所需信息的方式去解读现实，从而无法走向成功。</em></p><p>在任何给定的情境中，你可以有1000种不同的解读方式。也许其中5种解读能帮你成功，但你的心智却无法理解那5种方式。</p><p>你无法取得进展，是因为你的心智<em>拒绝</em>了你取得进展所需要的信息。</p><p>这远远不止是从一本书里获取信息那么简单。</p><p>你与失败的关系是怎样的？你是把它视为唯一可靠的、能作为决策依据的信息来源？还是把它当作缩回自己的洞里、放弃努力的理由？</p><p>你难道没意识到，成长就像做一只龙虾？</p><p>长得太大而撑不进原来的壳，这是<em>痛苦</em>的。而如果你不脱掉它，痛苦只会不断加剧，直到<em>死亡</em>。如果你决定脱壳——大多数人不会——你就会变得<em>脆弱</em>。你会经历一段重新长出新壳的时期。</p><p>顺便说一句，那个壳就是你的身份认同。</p><p>而你的身份认同主要是通过两种方式形成的：</p><ol><li><strong>社会规训：</strong>你继承了父母、老师和朋友的目标或游戏。作为孩子，你是一块吸收知识的海绵，还分不清对错。</li><li><strong>概念性生存：</strong>人类会注意并记住那些有助于自己生存的信息。这是我们大脑的天生构造。</li></ol><p>问题是，我们不是动物，而且我们大多数人并不像祖先那样，时刻面临被熊攻击的威胁。</p><p>人类不仅像动物那样试图保护和繁衍自己的肉体形态。他们也不只是想传递基因中的信息。他们还在保护和繁衍自己的<em>身份认同——他们心智或概念层面的形态</em>。他们试图传递意识中承载的信息。</p><p>这就是为什么我们要写书。这就是为什么当有人挑战我们的政治意识形态时，我们会感到被冒犯并反唇相击——试图把自己的信念植入对方的心智。这就是为什么当我们没有在朝着目标前进时，我们会感到压力。</p><p>你几乎所有的痛苦、不安全感和停滞不前，归根结底都在于你被困在低我的外壳里，而这个低我正竭尽全力维持现状不变。你拒绝打开心智，拒绝脱掉这层壳，所以你根本<em>看不到</em>一种更好的生活其实<em>是</em>可能的。</p><p>你的身份认同不是什么与生俱来、连同你的名字一起被指定好、一成不变的东西。它是一个活生生的、有呼吸的、不断演化的实体。</p><p>你并不是无助的。</p><p>你只是学会了表现得无助。</p><h3 id="_2-——-错误是唯一的真理来源" tabindex="-1">2 —— 错误是唯一的真理来源 <a class="header-anchor" href="#_2-——-错误是唯一的真理来源" aria-label="Permalink to &quot;2 —— 错误是唯一的真理来源&quot;">​</a></h3><p>事情是这样的：</p><p>大多数人一次又一次地尝试，却一次又一次地失败，因为他们试图用别人的地图去套自己的领地。</p><p>课程、书籍、播客。</p><p>他们没有意识到，这些东西<em>本身就是</em>地图。</p><p>它们是向导，不是真理。它们有用，但前提是你要明白，它们不过是黑暗房间里远处的一盏烛光，指引你穿过黑暗——它们并不能决定你脚下每一步的方向，也无法保证你不会一脚踩进蛇窝。</p><p>更进一步说，你没办法进入别人的心智状态。你没办法了解<em>他们</em>是如何感知这个世界的。你的身份认同和他们的也不完全相同。</p><p><strong>这引出了一个至关重要而又违反直觉的认知：</strong></p><p>错误是唯一的真理来源。</p><p>不是你脑子里的想法。不是某个亿万富翁的建议。</p><p>失败是唯一一位百分之百完全为你的情况量身定制的老师。</p><p>失败的信噪比是100:1。</p><p>但你憎恨失败。</p><p>你让它主宰了你的生活。</p><p>你忽视它，转而把头埋进更多的课程、书籍和播客里。</p><p>你所学到的一切、只要不是从错误中提炼出来的，就都是源自理论。它们源自一张地图。它们只是别人对自己所犯错误进行解读之后，形成的一种推测而已。</p><p>这就引出了一个问题：</p><p>你要如何朝着正确的方向犯下更好的错误，并从这些错误中学习，从而走向成功？</p><p>最后，作为这篇文章的结尾，你要如何在还没开始之前就先经历一次失败，从而立刻开始学习？</p><h2 id="如何用战略思维改变你的人生" tabindex="-1">如何用战略思维改变你的人生 <a class="header-anchor" href="#如何用战略思维改变你的人生" aria-label="Permalink to &quot;如何用战略思维改变你的人生&quot;">​</a></h2><blockquote><p>战略不是一份冗长的行动计划。它是一个核心理念在不断变化的环境中不断演化的过程。</p><p>劳伦斯·弗里德曼</p></blockquote><p>大多数人的人生之所以平庸，是因为缺乏战略性思维。</p><p>而成功的人则截然不同，他们高度具有战略性。</p><p>他们不会任由生活随意摆布自己。他们拒绝了被指定好的默认路径。他们会为自己理想的生活选择想要玩的那场游戏，也会选择那些能带他们通往目标的中间游戏。他们通过技能习得和学习，把自己塑造成能够赢得那场游戏的人。</p><p>所以，要想赢得你选择去玩的任何一场游戏，你都需要一套策略。</p><p><a href="https://app.kortex.co/public/document/564f7219-7cf6-4cdd-86e2-e71895631781" target="_blank" rel="noreferrer">→ 这里有一份文档，你可以在阅读的同时依次填写。</a></p><p>如果你下载了Kortex的桌面应用，你可以在阅读时按下Alt或Option+D，打开一个悬浮笔记。</p><p>接下来进入策略部分：</p><h3 id="_1-——-战略意图" tabindex="-1">1 —— 战略意图 <a class="header-anchor" href="#_1-——-战略意图" aria-label="Permalink to &quot;1 —— 战略意图&quot;">​</a></h3><p>你需要方向。</p><p>你需要一个新的目标，让你的心智能以此为出发点去解读这个世界。</p><p>首先，想一想你对目前生活中<em>讨厌</em>的一切。</p><p>那份工作？那副身材？你的日常作息？你的感受如何？从某个地方开始就好。</p><p>其次，想一想关于你未来生活的几种潜在可能性。</p><p>开创一份事业。保持健康、充满能量。活出<em>属于你自己</em>的理想的一天。</p><p>不要在这上面纠结太久。写下几点，然后继续往下走。</p><p>选择你想要玩的那场宏观游戏。</p><h3 id="_2-——-自我分析" tabindex="-1">2 —— 自我分析 <a class="header-anchor" href="#_2-——-自我分析" aria-label="Permalink to &quot;2 —— 自我分析&quot;">​</a></h3><p>很明显，你目前的身份认同并没有在为你服务。</p><p>所以，你需要通过做一次SWOT分析，来意识到自己所有的卡点。</p><ul><li><strong>优势（Strengths）</strong>——很简单，你的优势和才能是什么？什么事情对你来说很容易？如果你用“没有”这种敷衍的答案来回应，那你就是在说谎，而且已经无法看穿你的低层自我像机器人一样往你脑子里塞的那些反应了。再想深一点。</li><li><strong>劣势（Weaknesses）</strong>——你在哪些方面出了名地差，这又是如何影响你的进展的？</li><li><strong>成长机会（Opportunities for Growth）</strong>——什么可以帮你克服劣势、发挥优势的杠杆作用？这可能是学习技能、上课程、认识新的人等等。</li><li><strong>威胁（Threats）</strong>——什么威胁着你的进展？可能是朋友邀你出去玩、时间不够、害怕失败等等。</li></ul><p>顺便说一句，我把上一篇信里提到的<a href="https://app.kortex.co/public/document/564f7219-7cf6-4cdd-86e2-e71895631781" target="_blank" rel="noreferrer">战略顾问提示词（Strategic Advisor prompt）</a>升级了。</p><p>我建议你复制这份文档，把它粘贴进 Kortex AI，把你的整套策略写在一份文档里，然后让 kAI 引导你完成它。</p><p>以下是我请它就“打造受众”给出指导时，它给出的一个例子：</p><p><img src="'+t+'" alt=""></p><p>然后我就可以让 kAI 帮我了解上面提到的任何一点，并沿途引导我。</p><h3 id="_3-—-战略性准备" tabindex="-1">3 — 战略性准备 <a class="header-anchor" href="#_3-—-战略性准备" aria-label="Permalink to &quot;3 — 战略性准备&quot;">​</a></h3><p>你要如何改变自己的身份认同，才能轻松地根据策略去行动？</p><p>你要从把自己沉浸在一个全新的环境中开始。</p><p>你要改变你读的书、你摄入的信息、你关注的人，以及其他一切，让它们都反映出你正在努力实现的目标。</p><p>你要向新的视角敞开心智，让它们挑战你对“什么是可能的”这一信念。</p><p>删掉手机上大部分的App。取关你关注的大部分人。买3本新书。排好一些播客，走路时听。投入资源去学习你需要学的技能。提前写好一条信息，用来拒绝朋友邀你出去玩。</p><p>任何不符合你目标的东西，按定义都是干扰。</p><p>你需要一个只利于你实现目标的环境。</p><h3 id="_4-—-兵力集中" tabindex="-1">4 — 兵力集中 <a class="header-anchor" href="#_4-—-兵力集中" aria-label="Permalink to &quot;4 — 兵力集中&quot;">​</a></h3><p>正如我们在上一篇信里讨论过的，让目标落地成真的唯一方式，就是建立一个现实世界中的项目。</p><p>你是靠挣扎去学习的，不是靠死记硬背，而你需要一个项目来应用你的学习成果，所以：</p><ul><li>写下3到5个你<em>可能</em>用来实现目标的项目。</li><li>选出杠杆最高、结果最有利的那个项目。</li><li>规划出3到5项你可以每天去做、能推动这个项目进展的优先任务。</li></ul><p>如果你想辞掉工作、做自己的事，一个例子项目就是开始做一份每周简报，或者开始做社交媒体。社交媒体的杠杆可能是最高的，因为它能建立受众，而简报则可以随后跟进。</p><p>当然，这可能不是你的兴趣所在，但如果是的话，<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时写作者（2 Hour Writer）</a>可能会对你有帮助。</p><h3 id="_5-—-有纪律的执行" tabindex="-1">5 — 有纪律的执行 <a class="header-anchor" href="#_5-—-有纪律的执行" aria-label="Permalink to &quot;5 — 有纪律的执行&quot;">​</a></h3><p>你需要用一套新的routine（日常习惯）来取代旧的那一套。</p><p>因为你现在的日常习惯，很可能是你在不知不觉中“陷入”的。</p><p>而如果你的行动塑造了你的未来，那你就是在不知不觉中陷入某个未来——而这个未来，你大概根本不会在乎。</p><ul><li>在早上花1到2个小时，或晚上花1到2个小时，去执行你那3到5项撬动杠杆的优先任务。</li><li>你一天里做的每件事都应该为你的工作添柴加火。你读的东西。你刷的东西。你的对话。去散步而不是让自己分心。好好吃饭。</li><li>你脑子里应该只想着一件事：该怎么想策略，去克服这场游戏中的障碍。</li></ul><p>等我们不久后一起制作一份“事前验尸（Pre-Mortem）”，这一切就会变得顺理成章。</p><h3 id="_6-—-适应能力" tabindex="-1">6 — 适应能力 <a class="header-anchor" href="#_6-—-适应能力" aria-label="Permalink to &quot;6 — 适应能力&quot;">​</a></h3><p>策略就像生活中的其他一切一样。</p><p>它不是静止不变的。</p><p>它会随着反馈而演化。</p><p>你需要能够识别出什么时候事情不奏效了，回到你的策略上，然后尝试一些新的东西。</p><p>记住，错误才是唯一的真相之源。</p><p>实验就是你犯错的方式，因此，实验也是你在生活中实现所想之事的唯一途径。</p><h3 id="_7-—-研究自然的普遍法则" tabindex="-1">7 — 研究自然的普遍法则 <a class="header-anchor" href="#_7-—-研究自然的普遍法则" aria-label="Permalink to &quot;7 — 研究自然的普遍法则&quot;">​</a></h3><p>如果你理解了贯穿在你所做每一件事中的普遍法则，那么读懂一个负面处境就会变得容易得多。</p><p>在我看来，理解这一点最简单的方式，就是理解故事的结构。</p><p>首先，有一个需要解决的问题。主人公必须经历高潮和低谷。有挣扎。也有极乐。</p><p>就像海洋中的波浪、你心智里的情绪、你人际关系的发展一样，在现实的所有层面上、在每一种情境中，你都身处一句话之中，这句话属于一段话，这段话属于一个章节，这个章节属于一部永无止境的系列丛书。</p><p>如果你能识别出自己身处故事中的哪一部分，而不是固执地认为它应该永远保持原样，走出困境就会变得容易得多。</p><p>如果你想更深入地理解这一点，一本很棒的短篇书籍是《The Kybalion》。</p><h2 id="事前验尸-pre-mortem-如何在开始之前就先失败一次" tabindex="-1">事前验尸（Pre-Mortem）：如何在开始之前就先失败一次 <a class="header-anchor" href="#事前验尸-pre-mortem-如何在开始之前就先失败一次" aria-label="Permalink to &quot;事前验尸（Pre-Mortem）：如何在开始之前就先失败一次&quot;">​</a></h2><blockquote><p>策略的本质，就是选择不做什么。</p><p>迈克尔·波特（Michael Porter）</p></blockquote><p>大多数人失败，不是因为他们完不成自己的项目。</p><p>他们失败，是因为一些内在的、心理层面的思维过程掌控了他们的注意力，让他们相信成功是不可能的。</p><p>举几个例子：</p><ul><li>分析瘫痪症（过度研究，却不采取行动）</li><li>因为别人的看法而失去对宏大愿景的关注</li><li>缺乏辅助性的技能，比如写作和打造受众的能力，因而找不到为你的作品买单的顾客</li><li>经济上的不安全感,严重到让你接受“我需要专注于那份我讨厌的工作”这个念头</li><li>精疲力竭，却没有能让自己重新焕发活力的应对机制</li><li>对那些能带来结果的平凡工作感到厌烦</li><li>渴望去做一件看起来花哨、地位高的事，而不是一件你真正喜欢、或能让你脱离当下境况的事</li></ul><p>当你身处一个项目正中间的时候,让心智敞开去看到你处境之外的东西，是极其困难的。你会陷入一种被压力主宰的、目光狭隘的生存模式。你想不出解决方案，只能想到问题。</p><p>绕开这一点最好的办法，就是做一次“事前验尸”。</p><p>“事前验尸”是一种战略思维工具，它能在任何项目开始之前，就找出其中的<em>失败点</em>。</p><p>这里说的“项目”，可以是任何东西：辞职、转行、寻找人生目标、自我教育、减肥、改善关系、规划你的一年，或者其他任何真正的事。</p><p>具体怎么做，如下。</p><p>首先，选定你的项目，或者使用上面提到的策略——这一切都已经写在<a href="https://app.kortex.co/public/document/564f7219-7cf6-4cdd-86e2-e71895631781" target="_blank" rel="noreferrer">前面提到的模板</a>里，等着你填写。然后：</p><ul><li><strong>想象一次惨烈的失败</strong>——把你的策略惨败的样子在脑中可视化出来。它看起来什么样？你的人生最终落到了哪里？</li><li><strong>列出失败的原因</strong>——头脑风暴出<em>所有</em>可能导致失败的原因。要包括心理层面的原因，比如个人的弱点、自我破坏、知识或技能的欠缺，也要包括外部因素，比如钱不够。</li><li><strong>给清单排序</strong>——重新整理这份清单，把<em>威胁最大</em>的排在最前面。</li><li><strong>头脑风暴解决方案</strong>——针对每一个失败原因，头脑风暴出可能的解决方案。可以把 kAI 当作你的战略顾问，请它帮你完成这一步。</li></ul><p>当策略和事前验尸都完成之后，你应该会感觉相当清楚——知道自己该做什么，才能防止你的下一个项目失败。</p><p>希望以上这一切都对你有所帮助。</p><p>也希望你不是只是读完这些，却什么都没有付诸实践。</p><p>祝你这周剩下的时间愉快。</p><p>——Dan</p><hr><p><a href="/en/letters/why-you-fail-at-almost-everything-you-do">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',168))])}const y=r(m,[["render",c]]);export{q as __pageData,y as default};
